node --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
import { installVendor } from './tools/node-vendor.mjs';
registerHooks({resolve(specifier, context, nextResolve) {
  if (specifier.startsWith('.') && specifier.endsWith('.js')) {
    const url = new URL(specifier, context.parentURL);
    url.pathname = url.pathname.replace('/dist/', '/src/').replace(/\.js$/, '.ts');
    if (existsSync(url)) return nextResolve(url.href, context);
  }
  return nextResolve(specifier, context);
}});
await installVendor({ reference: true });
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { benchCase, evaluate } = await import('./src/typed/evaluate.ts');
const { storeOf } = await import('./src/typed/ir.ts');
const { lowerToImage, imageFromCode, runImage } = await import('./src/typed/backend/index.ts');
const { createIRArtifact } = await import('./src/framework/ir/adapters.ts');
const { BindingsIR } = await import('./src/typed/specialize.ts');
const assert = (await import('node:assert/strict')).default;
const source = \`
function dot3(a: f32, b: f32, c: f32, d: f32, e: f32, f: f32): f32 {
    return (a * b + c * d) + e * f;
}
function probe(work: buffer, table: buffer, n: i32): i32 {
    let j: i32 = 0;
    for (let i: i32 = 0; i < n; i = i + 1) {
        const k: i32 = (8 / n) * (j & 1);
        const x: f32 = work.getF32(i);
        work.setF32(i, dot3(x, table.getF32(k), 1.0, 0.5, 1.0, 0.25));
        j = j ^ 1;
    }
    return n >> 1;
}\`;
const inputs = {probe: {
  work: {floats:[4,4], range:[-1,1]},
  table: {cells:[0,16384,0,49024,0,16128,0,16256]},
  n: {oneOf:[2,4]},
}, dot3: Object.fromEntries([... 'abcdef'].map(k => [k,[-1,1]]))};
const ps = projectSource('dsp-probe', {'main.typed':source, 'project.json':JSON.stringify({pipeline:'speed',sources:['main.typed'],focus:8,inputs})});
const p = Program.fromProject(ps);
assert.equal(p.status,'ok',JSON.stringify(p.error));
assert.equal(ps.meta.pipeline,'speed');
const compiled = globalThis.typedRv32.compile(ps.source, [], undefined);
const ref = imageFromCode('probe', compiled.image, compiled.entries);
const compare = image => p.check({count:10, against:(fn,c) => runImage(image, fn, c.args, c.memory,{limit:200000})});
for (const image of [ref, lowerToImage(p.head).image]) {
 const checks = compare(image); assert(checks.fns.every(f => f.agree === 10 && !f.bothTrap), JSON.stringify(checks));
}
const run = p.exec('probe', [[0,16256,0,49152,0,16256,0,16256], inputs.probe.table.cells, 4], {limit:20000});
assert.deepEqual(run.buffers[0].cells, [0,16432,0,48896,0,16432,0,16288]);
const st = storeOf(p.origin.value);
const c = benchCase(st, 'probe', {...inputs.probe,n:4});
assert.equal(evaluate(st,'probe',c.args,c.memory,{limit:20000}).steps, run.steps);
const bindings = createIRArtifact(BindingsIR,'probe-fixed-size',{formatVersion:1,source:'probe',bindings:[{fn:'probe',param:'n',value:4,entity:'probe#n'}]});
await p.specialize(bindings);
const pipeline = await p.pipeline('speed');
const exact = p.check({count:10});
assert(exact.fns.every(f=>f.agree===10 && !f.bothTrap),JSON.stringify(exact));
const rv = compare(lowerToImage(p.head).image);
assert(rv.fns.every(f=>f.agree===10 && !f.bothTrap),JSON.stringify(rv));
console.log(JSON.stringify({status:p.status, exact:exact.fns, rv:rv.fns, sampleIRSteps:run.steps, sampleResult:run.result, sampleCells:run.buffers[0].cells, revisions:p.rev, rejected:pipeline.steps.filter(s=>s.rejected).map(s=>s.rejected)}));
NODE

