node --input-type=module <<'NODE'
import { registerHooks, stripTypeScriptTypes } from 'node:module';
import { existsSync, readFileSync } from 'node:fs';
import { installVendor } from './tools/node-vendor.mjs';
import assert from 'node:assert/strict';
registerHooks({
  resolve(s, c, next) {
    if (s.startsWith('.') && s.endsWith('.js')) {
      const url = new URL(s, c.parentURL);
      url.pathname = url.pathname.replace('/dist/', '/src/').replace(/\.js$/, '.ts');
      if (existsSync(url)) return next(url.href, c);
    }
    return next(s, c);
  },
  load(url, c, next) {
    if (!url.endsWith('.ts')) return next(url, c);
    return {format:'module', source:stripTypeScriptTypes(readFileSync(new URL(url),'utf8'),{mode:'transform'}),shortCircuit:true};
  }
});
await installVendor({ reference: true });
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { lowerToImage, runImage } = await import('./src/typed/backend/index.ts');
const { referenceCompile, referenceRun } = await import('./src/typed/reference.ts');
const { createIRArtifact } = await import('./src/framework/ir/adapters.ts');
const { BindingsIR } = await import('./src/typed/specialize.ts');
const source = \`
function dot3(a: f32, b: f32, c: f32, d: f32, e: f32, f: f32): f32 {
    return (a * b + c * d) + e * f;
}
function probe(work: buffer, table: buffer, n: i32): i32 {
    let j: i32 = 0;
    for (let i: i32 = 0; i < n; i = i + 1) {
        const k: i32 = (4 / n) * (j & 1);
        const x: f32 = work.getF32(i);
        work.setF32(i, dot3(x, table.getF32(k), 1.0, 0.5, 1.0, 0.25));
        j = j ^ 1;
    }
    return n >> 1;
}\`;
const inputs = {probe: {
  work: {floats:[4,4], range:[-1,1]},
  table: {cells:[0,16384,0,49024,0,16128,0,16256]},
  n: {oneOf:[2,4]},
}, dot3: Object.fromEntries([... 'abcdef'].map(k => [k,[-1,1]]))};
const ps = projectSource('dsp-probe', {'main.typed':source, 'project.json':JSON.stringify({pipeline:'speed',sources:['main.typed'],focus:8,inputs})});
const p = Program.fromProject(ps);
assert.equal(p.status,'ok',JSON.stringify(p.error));
assert.equal(ps.meta.pipeline,'speed');
const ref = referenceCompile(ps.source);
const compare = against => {
 const checks = p.check({count:10, against});
 assert(checks.fns.every(f => f.agree === 10 && !f.bothTrap), JSON.stringify(checks));
 return checks.fns.map(f => [f.fn, f.agree]);
};
const workbenchImage = () => {
 const image = lowerToImage(p.head).image;
 return (fn,c) => runImage(image, fn, c.args, c.memory,{limit:200000});
};
console.log('r0 reference',compare((fn,c)=>referenceRun(ref,fn,c.args,c.memory,{limit:200000})));
console.log('r0 workbench',compare(workbenchImage()));
const run = p.exec('probe', [[0,16256,0,49152,0,16256,0,16256], inputs.probe.table.cells, 4], {limit:20000});
assert.deepEqual(run.buffers[0].cells, [0,16432,0,16432,0,16432,0,48768]);
console.log('fixed sample',run.steps,run.result,run.buffers[0].cells);
const bindings = createIRArtifact(BindingsIR,'probe-fixed-size',{formatVersion:1,source:'probe',bindings:[{fn:'probe',param:'n',value:4,entity:'probe#n'}]});
await p.specialize(bindings);
const pipeline = await p.pipeline('speed');
assert.equal(pipeline.steps.filter(s=>s.rejected).length,0,JSON.stringify(pipeline));
console.log('specialized r0 and RV32',compare(undefined),compare(workbenchImage()),'revisions',p.rev);
