node --input-type=module <<'NODE'
import { registerHooks, stripTypeScriptTypes } from 'node:module';
import { existsSync, readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { installVendor } from './tools/node-vendor.mjs';
registerHooks({
  resolve(s,c,next) {
    if (s.startsWith('.') && s.endsWith('.js')) {
      const url = new URL(s,c.parentURL);
      url.pathname = url.pathname.replace('/dist/','/src/').replace(/\.js$/,'.ts');
      if (existsSync(url)) return next(url.href,c);
    }
    return next(s,c);
  },
  load(url,c,next) {
    return url.endsWith('.ts') ? {format:'module',source:stripTypeScriptTypes(readFileSync(new URL(url),'utf8'),{mode:'transform'}),shortCircuit:true} : next(url,c);
  }
});
await installVendor({reference:true});
const { Program } = await import('./src/typed/program.ts');
const { projectSource } = await import('./src/typed/project.ts');
const { createArtifact } = await import('./src/framework/contracts/definitions.ts');
const { BindingsIR } = await import('./src/typed/specialize.ts');
const { referenceCompile,referenceRun } = await import('./src/typed/reference.ts');
const { lowerToImage,runImage } = await import('./src/typed/backend/index.ts');
const source = \`
function dot3(a:f32,b:f32,c:f32,d:f32,e:f32,f:f32):f32 { return (a*b+c*d)+e*f; }
function probe(work:buffer,table:buffer,n:i32):i32 {
  let j:i32=0;
  for (let i:i32=0; i<n; i=i+1) {
    const k:i32=(4/n)*(j&1);
    const x:f32=work.getF32(i);
    work.setF32(i,dot3(x,table.getF32(k),1.0,0.5,1.0,0.25));
    j=j^1;
  }
  return n>>1;
}
\`;
const inputs={probe:{work:{floats:[4,4],range:[-1,1]},table:{cells:[0,16384,0,49024,0,16128,0,16256]},n:{oneOf:[2,4]}},dot3:Object.fromEntries(Array.from('abcdef',x=>[x,[-1,1]]))};
const ps=projectSource('dsp-probe',{'main.typed':source,'project.json':JSON.stringify({sources:['main.typed'],pipeline:'speed',focus:5,inputs})});
const p=Program.fromProject(ps);
assert.equal(p.status,'ok',JSON.stringify(p.error));
assert.equal(ps.meta.pipeline,'speed');
const ref=referenceCompile(ps.source);
const verify=against=>{
  const {fns}=p.check({count:10,against});
  assert(fns.every(f=>f.agree===10&&!f.bothTrap&&!f.inconclusive),JSON.stringify(fns));
  return fns.map(f=>[f.fn,f.agree]);
};
const emu=()=>{
 const image=lowerToImage(p.head).image;
 return (fn,c)=>runImage(image,fn,c.args,c.memory,{limit:2e5});
};
console.log('r0 reference',verify((fn,c)=>referenceRun(ref,fn,c.args,c.memory,{limit:2e5})));
console.log('r0 workbench',verify(emu()));
const run=p.exec('probe',[[0,16256,0,49152,0,16256,0,16256],inputs.probe.table.cells,4],{limit:2e4});
assert.deepEqual(run.buffers[0].cells,[0,16432,0,16432,0,16432,0,48768]);
console.log('fixed sample',run.steps,run.result,run.buffers[0].cells);
const bindings=createArtifact(BindingsIR,'probe-fixed-size',{formatVersion:1,source:'probe',bindings:[{fn:'probe',param:'n',value:4,entity:'probe#n'}]});
await p.specialize(bindings);
assert.equal(p.inputs.probe.n,4);
const pipeline=await p.pipeline('speed');
assert(!pipeline.steps.some(s=>s.rejected),JSON.stringify(pipeline));
console.log('specialized r0 and RV32',verify(),verify(emu()),'revisions',p.rev);
NODE
